2350	__global__ void fused_left_looking_tile(
2351	    const float* __restrict__ input,
2352	    float* __restrict__ output
2353	) {
2354	    constexpr int LD = N + 1;
2355	    extern __shared__ float tile[];
2356	    const int tid = threadIdx.x;
2357	    const long long base = static_cast<long long>(blockIdx.x) * N * N;
2358	    const float* src = input + base;
2359	    float* dst = output + base;
2360	
2361	    for (int index = tid; index < N * N; index += blockDim.x) {
2362	        const int row = index / N;
2363	        const int col = index - row * N;
2364	        tile[row * LD + col] = row >= col ? src[index] : 0.0f;
2365	    }
2366	    __syncthreads();
2367	
2368	    for (int k = 0; k < N; ++k) {
2369	        if (tid == 0) {
2370	            float diagonal = tile[k * LD + k];
2371	            for (int j = 0; j < k; ++j) {
2372	                const float value = tile[k * LD + j];
2373	                diagonal = fmaf(-value, value, diagonal);
2374	            }
2375	            tile[k * LD + k] = sqrtf(fmaxf(diagonal, 1.0e-30f));
2376	        }
2377	        __syncthreads();
2378	
2379	        const float diagonal = tile[k * LD + k];
2380	        for (int row = k + 1 + tid; row < N; row += blockDim.x) {
2381	            float value = tile[row * LD + k];
2382	            for (int j = 0; j < k; ++j) {
2383	                value = fmaf(-tile[row * LD + j], tile[k * LD + j], value);
2384	            }
2385	            tile[row * LD + k] = value / diagonal;
2386	        }
2387	        __syncthreads();
2388	    }
2389	
2390	    for (int index = tid; index < N * N; index += blockDim.x) {
2391	        const int row = index / N;
2392	        const int col = index - row * N;
2393	        dst[index] = tile[row * LD + col];
2394	    }
2395	}
