2397	template <int K>
2398	__device__ __forceinline__ void register_cholesky_step_32(
2399	    float (&row_values)[32],
2400	    int lane
2401	) {
2402	    float value = row_values[K];
2403	    #pragma unroll
2404	    for (int j = 0; j < K; ++j) {
2405	        const float pivot = __shfl_sync(0xffffffff, row_values[j], K);
2406	        if (lane >= K) {
2407	            value = fmaf(-row_values[j], pivot, value);
2408	        }
2409	    }
2410	
2411	    float inverse = 0.0f;
2412	    if (lane == K) {
2413	        const float positive = fmaxf(value, 1.0e-30f);
2414	        inverse = rsqrtf(positive);
2415	        value = positive * inverse;
2416	        row_values[K] = value;
2417	    }
2418	    inverse = __shfl_sync(0xffffffff, inverse, K);
2419	    if (lane > K) {
2420	        row_values[K] = value * inverse;
2421	    }
2422	    if constexpr (K + 1 < 32) {
2423	        register_cholesky_step_32<K + 1>(row_values, lane);
2424	    }
2425	}
