2495	template <int K>
2496	__device__ __forceinline__ void register_cholesky_step_64(
2497	    float (&row_values)[64],
2498	    float* tile,
2499	    float* inverse,
2500	    int group,
2501	    int lane,
2502	    bool active
2503	) {
2504	    constexpr int LD = 65;
2505	    float value = 0.0f;
2506	    if (active && lane >= K) {
2507	        value = row_values[K];
2508	        #pragma unroll
2509	        for (int j = 0; j < K; ++j) {
2510	            value = fmaf(-row_values[j], tile[K * LD + j], value);
2511	        }
2512	    }
2513	
2514	    if (active && lane == K) {
2515	        const float diagonal = sqrtf(fmaxf(value, 1.0e-30f));
2516	        row_values[K] = diagonal;
2517	        tile[K * LD + K] = diagonal;
2518	        inverse[group] = 1.0f / diagonal;
2519	    }
2520	    __syncthreads();
2521	
2522	    if (active && lane > K) {
2523	        value *= inverse[group];
2524	        row_values[K] = value;
2525	        tile[lane * LD + K] = value;
2526	    }
2527	    __syncthreads();
2528	
2529	    if constexpr (K + 1 < 64) {
